std::string validateEffectPreset(const EffectPreset& p,const EffectRegistry& registry) {
    const auto* d=registry.find(p.effectType,p.effectVersion);
    if (!validInstanceId(p.id) || !validUtf8(p.name) || p.name.empty() || p.name.size()>256
        || !d || p.values.size()!=d->parameters.size()) return "Invalid pedal preset identity, effect or controls.";
    for (std::size_t j=0;j<p.values.size();++j) if (!d->parameters[j].accepts(p.values[j])) return "Invalid pedal preset value.";
    return {};
}
